/**
 * Get county centroid by FIPS codes
 */
export function getCountyCentroidByFips(stateFips: string, countyFips: string): CountyCentroid | null {
    const geoid = stateFips.padStart(2, "0") + countyFips.padStart(3, "0");
    return COUNTY_CENTROIDS[geoid] || null;
}

/**
 * Get all counties in a state
 */
export function getCountiesByState(stateFips: string): { geoid: string; name: string; lat: number; lng: number }[] {
    const prefix = stateFips.padStart(2, "0");
    return Object.entries(COUNTY_CENTROIDS)
        .filter(([geoid]) => geoid.startsWith(prefix))
        .map(([geoid, data]) => ({ geoid, ...data }));
}
